/* BHDP knockout bracket — paste this entire file into OBS Custom CSS.
   CSS only. Native round contents and match updates are retained. */
body.bracket:has(#bracket-response-wrapper) {
  --bg-primary: #141c30;
  --bg-card: #17213a;
  --text-primary: #f5f7fc;
  --text-secondary: #a6b5d5;
  --text-tertiary: #6698ac;
  --border: #354776;
  --alert-success: #00d8b0;
  --alert-warning: #00ffc2;
  display: block !important;
  margin: 0 !important;
  padding: 16px 20px 24px !important;
  min-height: 100vh;
  height: auto !important;
  box-sizing: border-box;
  border-left: 5px solid #00ffc2;
  background: linear-gradient(to bottom, #1e284a, #141c30) fixed !important;
  color: #f5f7fc;
  font: 16px/1.25 Arial, Helvetica, sans-serif;
}
body.bracket:has(#bracket-response-wrapper) #siteHeader,
body.bracket:has(#bracket-response-wrapper) main > .subnav {
  display: none !important;
}
body.bracket:has(#bracket-response-wrapper) main {
  display: block !important;
  width: 100% !important;
  min-width: 0;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
}
body.bracket #bracket-response-wrapper {
  display: block;
  width: 100%;
  height: auto !important;
  margin: 0 !important;
  padding: 0 !important;
  overflow: visible !important;
}
body.bracket #bracket-response-wrapper,
body.bracket #bracket-response-wrapper * { box-sizing: border-box; }
body.bracket #bracket-response-wrapper > h1 { display: none !important; }
body.bracket #bracket-response-wrapper a { text-decoration: none !important; }
body.bracket #bracket-response-wrapper a:focus-visible {
  outline: 2px solid #00ffc2;
  outline-offset: 3px;
}
body.bracket #bracket-response-wrapper .bracket-wrapper {
  display: flex !important;
  flex-flow: row nowrap !important;
  align-items: stretch;
  gap: 18px;
  width: 100%;
  overflow: auto !important;
  padding: 12px 8px 20px 0;
  background: transparent;
}
body.bracket #bracket-response-wrapper .bracket-wrapper > ul {
  flex: 1 0 270px;
  min-width: 270px;
  margin: 0 !important;
  padding: 48px 0 0;
  list-style: none;
}
body.bracket #bracket-response-wrapper .bracket-wrapper > ul::before {
  padding: 10px 12px;
  border: 1px solid #354776;
  border-radius: 8px;
  background: linear-gradient(to bottom, #26396b, #1e305e);
  color: #00ffc2;
  font: 900 18px/1 Arial, Helvetica, sans-serif;
  letter-spacing: 1.5px;
  text-transform: uppercase;
}
/* Preserve flex-based vertical pairing between rounds. */
body.bracket #bracket-response-wrapper .bracket-wrapper > ul > li {
  padding-right: 20px;
}
body.bracket #bracket-response-wrapper .bracket-wrapper > ul:first-child > li {
  min-height: 102px;
}
body.bracket #bracket-response-wrapper .bracket-wrapper > ul:last-child > li { padding-right: 0; }
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score {
  display: flex !important;
  flex-direction: column !important;
  gap: 0;
  width: 100%;
  max-width: none;
  margin: 0 !important;
  padding: 4px !important;
  overflow: hidden;
  border: 1px solid #354776 !important;
  border-radius: 10px;
  background: linear-gradient(to bottom, #1e284a, #141c30) !important;
  color: #f5f7fc;
  box-shadow: 0 4px 12px rgb(0 0 0 / 20%);
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.in_progress > a.box-score,
body.bracket #bracket-response-wrapper .bracket-wrapper li.concluded > a.box-score {
  border: 3px solid transparent !important;
  padding: 2px !important;
  background:
    linear-gradient(to bottom, #1e284a, #141c30) padding-box,
    linear-gradient(120deg, #76ffe1, #00ffc2 35%, #008b79) border-box !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score {
  display: flex !important;
  flex-direction: column !important;
  gap: 3px;
  width: 100%;
  margin: 0;
  padding: 0;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player {
  display: grid !important;
  grid-template-columns: minmax(0, 1fr) 34px;
  gap: 6px;
  align-items: center;
  min-height: 36px;
  margin: 0;
  padding: 3px 5px 3px 9px !important;
  border-radius: 6px;
  background: #17213a !important;
  color: #f5f7fc !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player .name {
  display: block !important;
  order: 0 !important;
  min-width: 0;
  font: 700 16px/1.2 Arial, Helvetica, sans-serif !important;
  color: inherit !important;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  text-align: left;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player > .score {
  display: flex !important;
  order: 0 !important;
  align-items: center;
  justify-content: center;
  flex: none !important;
  width: 30px !important;
  height: 30px !important;
  margin: 0;
  padding: 0 !important;
  border: 0 !important;
  border-radius: 5px;
  background: linear-gradient(135deg, #30dbb7, #00b795 48%, #007a6a) !important;
  color: #fff !important;
  font: 900 20px/1 Arial, Helvetica, sans-serif !important;
  font-variant-numeric: tabular-nums !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player > .score:empty {
  visibility: hidden;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player.won,
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player.throwing,
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score:has(.live-scores > .player-1.throwing) > .name-and-score > .player-1,
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score:has(.live-scores > .player-2.throwing) > .name-and-score > .player-2 {
  background: linear-gradient(110deg, #76ffe1, #00ffc2 45%, #00a68c) !important;
  color: #111724 !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > .board-number {
  width: 28px;
  height: 28px;
  right: -4px;
  margin-top: -14px;
  border: 1px solid #00ffc2 !important;
  border-radius: 6px;
  background: #00ffc2 !important;
  color: #111724 !important;
  font: 900 14px/1 Arial, Helvetica, sans-serif;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > .board-number:empty { display: none !important; }
/* Keep the bracket compact: detailed live scores remain on the groups screen. */
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > :is(.live-scores, .averages, .match-round, .marker) {
  display: none !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.no-match > a.box-score { border-style: dashed !important; }
@media (max-width: 600px) {
  body.bracket:has(#bracket-response-wrapper) { padding: 10px !important; }
}

/* Same compact, self-contained logo banner as the groups screen. */
body.bracket #bracket-response-wrapper::before {
  content: "📍 Somerset & Dorset";
  display: flex;
  align-items: center;
  justify-content: flex-end;
  box-sizing: border-box;
  min-height: 96px;
  padding: 20px 10px 20px 70%;
  background-image: url("data:image/png;base64,"), url("data:image/png;base64,");
  background-repeat: no-repeat;
  background-position: left 10px center, center center;
  background-size: min(24%, 200px) auto, min(32%, 230px) auto;
  border-bottom: 1px solid #354776;
  color: #00ffc2;
  font: 800 clamp(13px, 1.4vw, 21px)/1.25 Arial, Helvetica, sans-serif;
  text-align: right;
}
@media (max-width: 600px) {
  body.bracket #bracket-response-wrapper::before {
    min-height: 76px;
    padding: 16px 4px 16px 70%;
    background-position: left 4px center, center center;
    background-size: 27% auto, 33% auto;
    font-size: 11px;
  }
}

/* Larger player names within the existing bracket cards. */
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player .name {
  font-size: 19px !important;
}

/* Unstarted assigned matches: a full-height board panel inside the card end.
   The native board marker is a sibling of the link, so overlay it on the
   link while reserving the same width inside both player rows. */
body.bracket #bracket-response-wrapper .bracket-wrapper li.boarded:not(.in_progress):not(.concluded):not(:has(> a.in-progress)) > a.box-score {
  padding-right: 50px !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.boarded:not(.in_progress):not(.concluded):not(:has(> a.in-progress)) > .board-number:not(:empty) {
  display: flex !important;
  position: absolute;
  top: 50%;
  right: 20px;
  transform: translateY(-50%);
  margin: 0 !important;
  width: 46px;
  height: 85px;
  align-items: center;
  justify-content: center;
  border: 0 !important;
  border-radius: 0 9px 9px 0;
  background: #00ffc2 !important;
  color: #111724 !important;
  font: 900 28px/1 Arial, Helvetica, sans-serif;
  pointer-events: none;
}
body.bracket #bracket-response-wrapper .bracket-wrapper > ul:last-child > li.boarded:not(.in_progress):not(.concluded):not(:has(> a.in-progress)) > .board-number:not(:empty) {
  right: 0;
}

/* Stronger leg scores and quieter losing-player names. */
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player {
  grid-template-columns: minmax(0, 1fr) 40px;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player > .score {
  width: 38px !important;
  height: 32px !important;
  font-size: 26px !important;
  font-weight: 900 !important;
  box-shadow: inset 0 1px 2px rgb(255 255 255 / 22%);
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player.lost .name {
  color: #a6b5d5 !important;
  opacity: 0.65;
}
/* Keep the unstarted board panel flush with the slightly taller card. */
body.bracket #bracket-response-wrapper .bracket-wrapper li.boarded:not(.in_progress):not(.concluded):not(:has(> a.in-progress)) > .board-number:not(:empty) {
  height: 89px;
}

/* Yellow board assignments for matches awaiting a start. */
body.bracket #bracket-response-wrapper .bracket-wrapper li.boarded:not(.in_progress):not(.concluded):not(:has(> a.in-progress)) > .board-number:not(:empty) {
  background: #ffb700 !important;
  color: #111724 !important;
}

/* Leg scores form full-height teal panels at the right edge of each row. */
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score {
  padding: 0 !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score {
  gap: 0;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player {
  grid-template-columns: minmax(0, 1fr) 44px;
  min-height: 42px;
  padding: 0 0 0 10px !important;
  border-radius: 0;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player > .score {
  align-self: stretch;
  width: 44px !important;
  height: auto !important;
  min-height: 42px;
  border-radius: 0;
  background: #00ffc2 !important;
  color: #111724 !important;
  box-shadow: none;
  font-size: 28px !important;
}
/* Rounded outer corners come from the match card's clipping. */
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player.won {
  background: #00ffc2 !important;
  color: #111724 !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player.lost {
  background: transparent !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player.won .name {
  color: #111724 !important;
}
/* Reserve the yellow panel on unstarted matches; don't reserve blank scores. */
body.bracket #bracket-response-wrapper .bracket-wrapper li.boarded:not(.in_progress):not(.concluded):not(:has(> a.in-progress)) > a.box-score {
  padding-right: 46px !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.boarded:not(.in_progress):not(.concluded):not(:has(> a.in-progress)) > a.box-score > .name-and-score > .player {
  grid-template-columns: minmax(0, 1fr);
  padding-right: 8px !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.boarded:not(.in_progress):not(.concluded):not(:has(> a.in-progress)) > a.box-score > .name-and-score > .player > .score:empty {
  display: none !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.boarded:not(.in_progress):not(.concluded):not(:has(> a.in-progress)) > .board-number:not(:empty) {
  height: 84px;
}

/* Explicit corner shapes: don't rely only on parent clipping. */
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player:first-child {
  border-top-left-radius: 7px !important;
  border-top-right-radius: 7px !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player:last-child {
  border-bottom-left-radius: 7px !important;
  border-bottom-right-radius: 7px !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player:first-child > .score {
  border-radius: 0 7px 0 0 !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player:last-child > .score {
  border-radius: 0 0 7px 0 !important;
}

/* Concluded matches have no border or gradient outline. */
body.bracket #bracket-response-wrapper .bracket-wrapper li.concluded > a.box-score,
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score:has(> .name-and-score > .player.won) {
  border: 0 !important;
  outline: 0 !important;
  border-radius: 10px !important;
  background: linear-gradient(to bottom, #1e284a, #141c30) !important;
  overflow: hidden !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.concluded > a.box-score > .name-and-score,
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score:has(> .name-and-score > .player.won) > .name-and-score {
  border-radius: 10px !important;
  overflow: hidden !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.concluded > a.box-score > .name-and-score > .player:first-child {
  border-top-left-radius: 10px !important;
  border-top-right-radius: 10px !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.concluded > a.box-score > .name-and-score > .player:last-child {
  border-bottom-left-radius: 10px !important;
  border-bottom-right-radius: 10px !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.concluded > a.box-score > .name-and-score > .player:first-child > .score {
  border-top-right-radius: 10px !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.concluded > a.box-score > .name-and-score > .player:last-child > .score {
  border-bottom-right-radius: 10px !important;
}

/* In-play throwing indicator: fixed dot column, without a row highlight. */
body.bracket #bracket-response-wrapper .bracket-wrapper li.in_progress > a.box-score > .name-and-score > .player,
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score.in-progress > .name-and-score > .player {
  grid-template-columns: minmax(0, 1fr) 10px 44px;
  background: #17213a !important;
  color: #f5f7fc !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.in_progress > a.box-score > .name-and-score > .player .name,
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score.in-progress > .name-and-score > .player .name {
  grid-column: 1;
  grid-row: 1;
  color: #f5f7fc !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.in_progress > a.box-score > .name-and-score > .player > .score,
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score.in-progress > .name-and-score > .player > .score {
  grid-column: 3;
  grid-row: 1;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.in_progress > a.box-score > .name-and-score > .player::after,
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score.in-progress > .name-and-score > .player::after {
  content: "";
  grid-column: 2;
  grid-row: 1;
  justify-self: center;
  align-self: center;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #00ffc2;
  visibility: hidden;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li:is(.in_progress, :has(> a.in-progress)) > a.box-score > .name-and-score > .player.throwing::after,
body.bracket #bracket-response-wrapper .bracket-wrapper li:is(.in_progress, :has(> a.in-progress)) > a.box-score:has(.live-scores > .player-1.throwing) > .name-and-score > .player-1::after,
body.bracket #bracket-response-wrapper .bracket-wrapper li:is(.in_progress, :has(> a.in-progress)) > a.box-score:has(.live-scores > .player-2.throwing) > .name-and-score > .player-2::after {
  visibility: visible;
}

/* Override the earlier throwing selectors, including the live-score state. */
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score > .name-and-score > .player.throwing,
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score:has(.live-scores > .player-1.throwing) > .name-and-score > .player-1,
body.bracket #bracket-response-wrapper .bracket-wrapper li > a.box-score:has(.live-scores > .player-2.throwing) > .name-and-score > .player-2 {
  background: #17213a !important;
  color: #f5f7fc !important;
}

/* More prominent board badge for matches currently in play. */
body.bracket #bracket-response-wrapper .bracket-wrapper li.in_progress > .board-number:not(:empty),
body.bracket #bracket-response-wrapper .bracket-wrapper li:has(> a.box-score.in-progress) > .board-number:not(:empty) {
  display: flex !important;
  align-items: center;
  justify-content: center;
  width: 42px;
  height: 42px;
  top: 50%;
  right: -4px;
  margin: 0 !important;
  transform: translateY(-50%);
  border: 2px solid #76ffe1 !important;
  border-radius: 9px;
  background: #00ffc2 !important;
  color: #111724 !important;
  font: 900 24px/1 Arial, Helvetica, sans-serif;
  box-shadow: 0 3px 8px rgb(0 0 0 / 30%);
}

/* Reserve a separate board-badge lane outside live cards, clear of scores. */
body.bracket #bracket-response-wrapper .bracket-wrapper li.in_progress,
body.bracket #bracket-response-wrapper .bracket-wrapper li:has(> a.box-score.in-progress) {
  padding-right: 70px !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper li.in_progress > .board-number:not(:empty),
body.bracket #bracket-response-wrapper .bracket-wrapper li:has(> a.box-score.in-progress) > .board-number:not(:empty) {
  right: 20px;
  width: 42px;
  height: 42px;
}
body.bracket #bracket-response-wrapper .bracket-wrapper > ul:last-child > li.in_progress,
body.bracket #bracket-response-wrapper .bracket-wrapper > ul:last-child > li:has(> a.box-score.in-progress) {
  padding-right: 50px !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper > ul:last-child > li.in_progress > .board-number:not(:empty),
body.bracket #bracket-response-wrapper .bracket-wrapper > ul:last-child > li:has(> a.box-score.in-progress) > .board-number:not(:empty) {
  right: 0;
}

/* Shared card width and board lane across all match states. */
body.bracket #bracket-response-wrapper .bracket-wrapper > ul > li {
  padding-right: 70px !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper > ul:last-child > li {
  padding-right: 50px !important;
}
/* Unstarted board panels stay inside the shortened card's right edge. */
body.bracket #bracket-response-wrapper .bracket-wrapper li.boarded:not(.in_progress):not(.concluded):not(:has(> a.in-progress)) > .board-number:not(:empty) {
  right: 70px;
}
body.bracket #bracket-response-wrapper .bracket-wrapper > ul:last-child > li.boarded:not(.in_progress):not(.concluded):not(:has(> a.in-progress)) > .board-number:not(:empty) {
  right: 50px;
}

/* Last 16 feeder lines: connect each pair to its quarter-final. */
body.bracket #bracket-response-wrapper .bracket-wrapper > ul.last_16 > li {
  background-image:
    linear-gradient(#6698ac, #6698ac),
    linear-gradient(#6698ac, #6698ac) !important;
  background-repeat: no-repeat !important;
  background-size: 1px 50%, 70px 1px !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper > ul.last_16 > li:nth-child(odd) {
  background-position: right bottom, right center !important;
}
body.bracket #bracket-response-wrapper .bracket-wrapper > ul.last_16 > li:nth-child(even) {
  background-position: right top, right center !important;
}
/* Continue each joined pair across the gap into the quarter-final card. */
body.bracket #bracket-response-wrapper .bracket-wrapper > ul.last_8 > li::before {
  content: "";
  position: absolute;
  left: -18px;
  top: 50%;
  width: 18px;
  height: 1px;
  background: #6698ac;
  pointer-events: none;
}

/* Remove the event banner without resizing the bracket or match cards. */
body.bracket #bracket-response-wrapper::before {
  content: none !important;
  display: none !important;
}
